"* { font-family: \"Inter\", \"Segoe UI\", \"Arial\"; }\n"
"QMainWindow, QWidget#centralwidget { background-color: #0B0B0D; }\n"
"QWidget#pageLogin, QWidget#pageRegister, QWidget#pageWelcome, QWidget#pageVehicle, QWidget#pageResults,\n"
